def check_inequality():
    for x3 in range(134, 200):
        lhs = 400 * x3**2
        rhs = (3 * x3 - 400) * (x3**3 - x3**2 + 5)
        if lhs >= rhs:
            print(f"x3={x3} works: lhs={lhs}, rhs={rhs}")

check_inequality()

def find_x4():
    for x3 in range(134, 10000):
        num = 80 * x3**2
        den = 3 * x3 - 400
        if den > 0 and num % den == 0:
            x4 = num // den
            # Check the condition x4 >= 1 + x3^2 * (x3 - 1) / 5
            if x4 >= 1 + (x3**2 * (x3 - 1)) / 5:
                print(f"Found: x3={x3}, x4={x4}")

find_x4()

